{
  "name": "NanoScanZ显微镜Z轴纳米定位台",
  "name_en": "NanoScanZ microscope Z nanopositioning stage",
  "manufacturer": "Prior Scientific",
  "description": "这是一种用于显微镜Z轴精密调焦和高度定位的纳米定位台，可进行绝对位移、相对位移、回零与位置读取，并可显示当前行程范围与单位。它常用于显微成像中的焦点扫描、样品高度调整和自动对焦相关实验。",
  "description_en": "This is a precision microscope Z-axis nanopositioning stage for fine focusing and height positioning. It supports absolute and relative motion, zeroing, and position readback, and can report travel range and motion units. It is commonly used for focus scans, sample height adjustment, and autofocus-related microscopy experiments.",
  "tag_hints": [
    "microscopy",
    "Z-axis nanopositioning",
    "focus scanning",
    "objective/sample height adjustment",
    "absolute and relative positioning",
    "micron motion control"
  ],
  "actions": [
    {
      "action_name": "auto-setup",
      "description": "初始化NanoScanZ定位台的控制项。",
      "description_en": "Initialize the NanoScanZ stage control items."
    },
    {
      "action_name": "auto-connect",
      "description": "连接NanoScanZ定位台并启用位置、单位和行程等读写功能。",
      "description_en": "Connect to the NanoScanZ stage and enable read/write access for position, units, and travel information."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开NanoScanZ定位台连接。",
      "description_en": "Disconnect the NanoScanZ stage."
    },
    {
      "action_name": "auto-moveAbsolutePositionHW",
      "description": "将定位台移动到指定绝对位置。",
      "description_en": "Move the stage to a specified absolute position."
    },
    {
      "action_name": "auto-setPositionHW",
      "description": "定义当前位置信息。",
      "description_en": "Define the current position value."
    },
    {
      "action_name": "auto-getPositionHW",
      "description": "获取相对位置。",
      "description_en": "Get the relative position."
    },
    {
      "action_name": "auto-getPositionABS",
      "description": "获取绝对位置。",
      "description_en": "Get the absolute position."
    },
    {
      "action_name": "auto-setPostionZeroHW",
      "description": "将当前位置设为零点。",
      "description_en": "Set the current position as zero."
    },
    {
      "action_name": "auto-getTravelRangeHW",
      "description": "获取行程范围。",
      "description_en": "Get the travel range."
    },
    {
      "action_name": "auto-moveZeroPositionHW",
      "description": "移动到零点位置。",
      "description_en": "Move to the zero position."
    },
    {
      "action_name": "auto-moveRelativePositionHW",
      "description": "按设定位移量进行相对移动。",
      "description_en": "Move the stage by a specified relative distance."
    },
    {
      "action_name": "auto-moveUpHW",
      "description": "沿Z轴向上移动定位台。",
      "description_en": "Move the stage upward along the Z axis."
    },
    {
      "action_name": "auto-moveDownHW",
      "description": "沿Z轴向下移动定位台。",
      "description_en": "Move the stage downward along the Z axis."
    },
    {
      "action_name": "auto-resetStageHW",
      "description": "复位定位台。",
      "description_en": "Reset the stage."
    },
    {
      "action_name": "auto-updateHardware",
      "description": "刷新定位台的当前位置与状态信息。",
      "description_en": "Refresh the stage position and status information."
    }
  ]
}

